def comparison(key, similar, diff, choice, definition=None, locator=None, cmp='CMP186'):
    s=sources[key]
    return dict(vendor=s['vendor'],product=s['product'],element_name=s['source_title'],element_type=s['element_type'],
        relationship='Recouvrement partiel',similarities=similar,differences=diff,flow_position=choice,
        term_choice=choice,definition_choice=definition or diff,
        **{k:v for k,v in s.items() if k.startswith('source_')},
        consulted_on=s['consulted_on'],status='proposed',source_refs=['U470','U471',s['id'],cmp],
        evidence_limits='Passage primaire consulté ; rapprochement limité au périmètre décrit, sans équivalence de catalogue, choix de solution ni réalisation Beaumanoir déduite.',
        **({} if locator is None else {})) | ({'source_locator':locator} if locator else {})

added={}
def add(id,key,similar,diff,choice,definition=None,locator=None):
    assert id not in added
    added[id]=comparison(key,similar,diff,choice,definition,locator)

add('D08','batch','Import de références produit depuis plusieurs sources.','Le Product Hub peut gouverner les maîtres ; le référentiel FLOW reste leur projection.','Product Reference exprime la référence utilisable par la Supply, indépendante du catalogue.','La réception est incluse ; créer, modifier ou supprimer les maîtres dans leurs applications reste externe.')
add('D01.f','journals','Mouvements et comptages actualisent les quantités suivies.','Les journaux Microsoft regroupent aussi des effets comptables et des actions opératoires.','Inventory Tracking désigne la tenue de la situation de stock.','FLOW établit les quantités à partir des faits reconnus ; la visibilité restitue cette situation et la logistique réalise les mouvements.')
add('D01.c','supplydemand','Lecture datée du disponible, des approvisionnements et des besoins.','La page décrit une consultation produit, pas une responsabilité transverse avec exigence de fraîcheur.','Inventory Visibility conserve le sens établi de visibilité du stock.','FLOW explicite provenance, fraîcheur et absence de double compte ; la consultation ne crée ni stock ni réservation.')
add('D02.b','pal','Des limites par groupes préservent des ressources pour d’autres demandes.','PAL traite des confirmations par groupe ; Supply Protection couvre aussi d’autres politiques de protection.','Supply Protection est plus large que Product Allocation dans ce sens SAP.','La capacité maintient les règles applicables ; leur calcul spécialisé relève notamment de Group Protection Decision.')
add('D02.c','reservation','Une quantité liée à une demande est protégée contre les prélèvements concurrents.','Les objets et modalités Oracle ne sont pas repris dans FLOW.','Reservation est retenu pour son effet d’opposabilité.','Seule la réservation bloque les usages concurrents ; affectation et engagement ne la créent pas implicitement (choix FLOW).')
add('D03.i','ps','L’ATP établit une disponibilité datée à partir des ressources et besoins.','PeopleSoft mêle promesse, réservation et traitement des pénuries dans le même chapitre.','Available-to-Promise conserve le terme établi, à une maille métier distincte.','FLOW calcule les possibilités de la situation de référence ; confirmer un engagement et réserver restent séparés.',locator='Available-to-Promise ; ATP lead days')
add('D03.k','ptp','La promesse peut intégrer les coûts des ressources effectivement mobilisées.','Cet appui et la première référence sont deux documents Oracle ; ils ne démontrent pas un consensus interéditeurs.','Profitable-to-Promise est un terme documenté notamment par Oracle.','FLOW compare les conséquences économiques des scénarios ; il ne présuppose ni marge unique ni pondération de tous les critères.',locator='Profitable to Promise')
add('D03.l','schedules','Un échéancier associe des quantités à plusieurs dates de livraison.','La page décrit l’échéancier et son traitement, sans isoler l’arbitrage qui le choisit.','Delivery Schedule nomme un résultat établi ; Decision précise la responsabilité FLOW.','FLOW distingue le choix d’un échéancier réalisable de son enregistrement dans la commande.')
add('D03.m','ps','Des règles ordonnent les demandes avant de leur attribuer les ressources.','L’exemple applique ces priorités dans la réservation ; FLOW isole leur détermination.','Order Prioritization explicite un arbitrage entre commandes.','Une priorité ne change à elle seule ni affectation, ni engagement, ni réservation.',locator='Inventory priority rules ; tri des demandes')
add('D05.d','pal','Les plafonds de consommation protègent les groupes de demande.','La configuration PAL ne constitue pas une méthode universelle de calcul des bonnes quantités.','Group Protection Decision indique ce qui est décidé, sans ambiguïté avec l’affectation.','FLOW choisit les quantités ou limites ; Supply Protection en maintient les règles applicables.')
add('D05.f','plans','Plusieurs plans permettent d’étudier des stratégies et de simuler leurs effets.','Master Planning englobe des calculs et traitements regroupés autrement dans FLOW.','Inventory Planning conserve la pratique de planification centrée sur le stock.','La capacité construit et adapte les scénarios ; elle mobilise les décisions spécialisées et leurs capacités d’application.')
add('D06.b','workload','Charge et capacité d’entrepôt peuvent être projetées par période.','Exemple limité à l’entrepôt, pas preuve d’une capacité communiquée par tout exécutant.','Service Capacity Visibility étend ce besoin de lecture aux services admissibles.','FLOW utilise une capacité contextualisée reçue des exécutants ; il ne reprend pas l’administration de leurs moyens.')
add('D07.b','tmf','Une commande de service peut être créée, modifiée et suivie.','TMF641 est un contrat sectoriel télécom ; le texte public ne démontre pas tous les états de FLOW.','Service Order Management dispose d’un appui lexical hors ERP.','FLOW garde le cycle métier des prestations demandées aux exécutants, sans importer API, états télécom ou catalogue technique.')
add('D08.d','batch','Des références et leurs éléments associés sont importés depuis des sources produit.','Le lot d’import est un mécanisme produit ; FLOW ne prescrit ni lot ni gouvernance de maître.','Product Reference Ingestion nomme la responsabilité de réception.','L’ingestion rend les références externes utilisables ; elle ne devient pas leur administration.')
add('D06.e','carrier','Le choix porte explicitement sur un transporteur et son service.','Cas transport et choix manuel dans un produit historique ; toutes les prestations ne sont pas documentées.','Service Selection Decision désigne le choix de l’exécutant et du service.','FLOW conserve les contraintes d’admissibilité ; le produit illustre ce résultat sans imposer l’outil ou la méthode.')
add('BHV006','plans','Les plans servent aussi à simuler des stratégies alternatives.','La documentation porte sur la planification ; tous les usages analytiques FLOW ne sont pas couverts.','Simulation & Analysis décrit une pratique de comparaison de scénarios.','Ce comportement éclaire une décision ou un plan, sans devenir un domaine autonome.')
add('BHV031','spot','Un comptage ponctuel peut être déclenché pendant une opération ciblée.','Oracle illustre un déclenchement par seuil au prélèvement, plus étroit que tous les motifs FLOW.','Spot Counting conserve le sens de vérification ponctuelle.','Le comportement ne se limite pas à une campagne périodique ni à un seuil logiciel imposé.')
add('BHV033','ps','Une fenêtre temporelle détermine quand commencer la réservation.','Le paramètre PeopleSoft est une réalisation possible, pas une règle générale de durée.','Time-Fenced Reservation Policy explicite l’horizon de protection.','FLOW conserve une politique métier conditionnelle ; aucun nombre de jours ni blocage anticipé implicite.',locator='Reservation lead days')
add('BHV036','plans','Un horizon de firming transforme des ordres planifiés en ordres fermes.','L’automatisme et l’horizon Microsoft ne sont pas obligatoires dans FLOW.','Order Firming reprend un terme établi de planification.','Le changement d’engagement est distingué du calcul préalable et de l’exécution physique.')
add('BHV044','schedules','Une ligne est répartie entre livraisons distinctes rattachées à son origine.','Cet exemple porte sur des lignes de livraison ; il ne couvre pas toutes les scissions de commandes.','Order Splitting décrit la scission ; Order Structuring inclut aussi les regroupements.','La filiation et les quantités doivent rester cohérentes ; les regroupements ne sont pas déduits de cette source.')
add('BHV047','pegging','Le stock reçu peut être réaffecté à des demandes antérieures selon les règles.','Microsoft combine protection de promesses et maintien du pegging ; FLOW sépare ces responsabilités.','Supply Reassignment désigne la révision des liens ressources–commandes.','Réaffecter reste soumis aux engagements modifiables ; une affectation seule ne réserve pas.')
add('BHV057','repair','Le fournisseur répare le bien et restitue le même exemplaire.','Le guide historique inclut des traitements financiers qui restent hors du comportement FLOW.','Return for Repair distingue réparation, remplacement et retour définitif.','L’attendu de restitution et l’identité du bien sont conservés, sans imposer le parcours logiciel.')
add('BHV058','po','Les commandes d’achat portent quantités et échéances d’approvisionnement.','Un Purchase Order peut aussi couvrir d’autres destinations que le stock.','Stock Procurement précise la destination du parcours d’achat.','FLOW suit ce qui reste à recevoir pour le réseau ; il ne reprend ni comptabilité ni structure d’écran ERP.')
add('BHV059','orchestration','Le drop shipment permet une livraison du fournisseur au client.','Le produit orchestre plusieurs types d’approvisionnement dans un même module.','Direct Delivery explicite le trajet métier, également appelé drop shipment.','Côté achat, FLOW coordonne les attendus fournisseur avec ceux de la vente ; le transport reste distinct.')
add('BHV061','ubl','Le stock de départ précède les réapprovisionnements de l’activité.','Les scénarios VMI/CRP ne sont pas tous consignés ; VMI et consignation ne sont pas synonymes.','Initial Stocking est un terme établi pour l’apport de départ.','FLOW l’applique ici au stock consigné et à son échéance de lancement.',locator='§2.3.3.5.2.2 ; §2.3.3.5.3.1 et §2.3.3.5.3.3')
add('BHV062','ubl','Les réapprovisionnements suivent l’activité et les mouvements de stock.','UBL décrit des échanges ; il ne prescrit ni propriété ni responsabilité unique du calcul.','Continuous Replenishment distingue les apports récurrents du démarrage.','FLOW porte les apports consignés successifs, sans imposer rythme ou algorithme.',locator='§2.3.3.5.2.4 ; §2.3.3.5.3.4')
add('BHV064','aging','Une durée contractuelle peut déclencher l’acquisition du stock consigné.','Deux générations Oracle documentent ce comportement ; cela ne prouve pas son universalité.','Aging-Based Ownership Transfer décrit cet effet contractuel précis.','Aucun délai fixe ni règle automatique ne sont ajoutés au contrat métier FLOW.')
add('BHV065','ubl','Le producteur peut demander le retour de marchandises.','L’exemple étaye la reprise, pas les autres sorties ni leurs autorisations contractuelles.','Consignment Exit reste un regroupement FLOW de sorties autorisées.','Reprise, soldeur, seconde main ou destruction restent conditionnés par les accords ; aucune décision de sortie nouvelle.',locator='§2.3.3.5.2.6 Returns Initiated by the Producer')
add('BHV066','storefulfillment','Le magasin peut expédier une commande au client.','L’exemple traite le magasin ; FLOW couvre aussi les autres lieux du réseau.','Ship to Customer est un parcours orienté destinataire.','Le comportement porte la commande à livrer ; préparer et transporter relèvent des exécutants.',locator='Shipping ; Line quantity tracking')
add('BHV067','storefulfillment','Le retrait client dispose d’une action distincte de la préparation.','Les états produit associent aussi facturation et retrait ; FLOW ne reprend pas cette assimilation.','Customer Pickup nomme le mode de remise au client.','Une commande prête ne prouve pas que le client l’a retirée.',locator='Pick ; Pick up')
add('BHV068','orchestration','Le fournisseur peut livrer directement le client.','Le module Oracle est une réalisation ; il ne fixe pas les frontières entre nos Orders.','Direct Delivery est conservé côté vente comme côté achat.','Côté vente, FLOW suit l’attendu client et sa coordination avec l’achat, sans détour physique imposé par le réseau.')
add('BHV069','intercompany','Les commandes de vente et d’achat intersociétés se correspondent.','La création automatique décrite par Microsoft n’est pas imposée par FLOW.','Intercompany Sales reprend le vocabulaire établi de vente entre entités juridiques.','La cohérence des engagements est attendue ; le mécanisme de synchronisation reste hors de la cartographie.')
add('BHV070','ubl','Un stock de base est constitué au début d’une saison.','UBL décrit une relation fournisseur–distributeur, pas un transfert interne : appui sémantique uniquement.','Initial Stocking précise le but du transfert, distinct du réassort courant.','FLOW applique ce motif au Transfer Order ; aucun achat ou transfert de propriété n’en est déduit.',locator='§2.3.3.5.3.3 Initial Stocking of the Area by Retailer')
added['BHV070']['relationship']='Appui sémantique'
add('BHV074','backtoback','Un transfert peut alimenter une commande identifiée avec un lien suivi.','Le flux Oracle peut maintenir un lien ferme ; cette règle produit ne vaut pas réservation implicite FLOW.','Order-Driven Transfer exprime le motif du transfert.','Le lien et l’échéance sont conservés ; la protection contre les demandes concurrentes reste du ressort de Reservation.')
add('BHV075','gop','Le CTP examine une fourniture à obtenir, notamment par fabrication.','Oracle distingue ses modes et règles ATP/CTP ; FLOW conserve sa propre situation de référence.','Additional Supply Feasibility explicite la possibilité de ressources supplémentaires.','Le comportement évalue les quantités, dates et conditions possibles ; il ne crée pas lui-même un ordre ferme.')
add('BHV076','ifo','Des stratégies évaluent différentes sources sous contraintes de satisfaction.','IFO réalise aussi l’optimisation ; ce comportement FLOW est limité à la faisabilité des alternatives.','Fulfillment Alternative Feasibility rend explicite l’objet de l’étude.','Changer de lieu ou de modalité crée une possibilité à examiner, pas un engagement automatique.')
add('BHV077','ps','La gestion des pénuries permet de revoir la couverture des demandes prioritaires.','Le workbench applique des changements ; FLOW distingue leur étude et leur application.','Commitment Rebalancing Feasibility nomme l’évaluation des engagements révisables.','Les conséquences sur les commandes restent explicites ; aucune promesse intangible n’est retirée automatiquement.',locator='Shortage Workbench ; unfulfill et priorités')
add('BHV079','warehouse','Le travail d’entrepôt en cours et restant peut être suivi.','Cette page illustre les sorties ; elle ne documente pas à elle seule les réceptions.','Warehouse Visibility indique le périmètre de visibilité.','FLOW reçoit les faits d’avancement ; afficher le travail ne signifie pas l’exécuter.')
add('BHV080','ubl','Les partenaires se transmettent les états d’acheminement.','Le scénario ne garantit ni temps réel ni calcul prédictif d’arrivée.','Transportation Visibility est éclairé par ces échanges de progression.','FLOW rend visibles les faits et estimations disponibles, sans réaliser le transport.',locator='§2.3.5.4 Freight Status Reporting')
add('BHV081','store','Des opérations et états de stock magasin sont suivis.','La page ne documente pas toute la mise en rayon et ses remontées.','Store Visibility délimite le contexte magasin.','FLOW conserve une lecture des faits reçus ; il ne reprend pas l’exécution des tâches magasin.')
add('BHV083','replenishment','La méthode Requirement calcule un approvisionnement par besoin.','FLOW ne prescrit pas un ordre distinct par besoin : le regroupement reste possible.','Requirement-based Replenishment désigne le raisonnement à partir des besoins.','Les ressources utilisables et apports attendus sont pris en compte ; la forme de la commande reste distincte.',locator='Coverage codes : Requirement')
add('BHV084','replenishment','Min./Max. réapprovisionne vers une cible après franchissement d’un seuil.','Cette méthode illustre le comportement sans épuiser les politiques de cible.','Target-based Replenishment couvre ce raisonnement par niveau de stock.','Les seuils et cibles sont explicites ; aucune commande client individuelle n’est requise pour chaque apport.',locator='Coverage codes : Min./Max. ; examples')
add('BHV085','plans','Des messages proposent d’avancer, retarder ou ajuster des ordres existants.','Les propositions Microsoft ne définissent pas toutes les limites de modification FLOW.','Replenishment Adjustment désigne la révision des apports prévus.','La décision respecte les engagements et reste distincte de sa mise en application.',locator='Action message time fence')
add('TER036','ubl','Un avis de réception rapporte les biens effectivement reçus.','Cet exemple documentaire ne démontre pas que tout événement possède un document.','Fait de gestion reste le sens métier adopté dans FLOW.','Le lien obligatoire fait–document est notre convention ; le document peut être un enregistrement structuré.',locator='§2.3.5.1.3 Receipt Advice Business Rules')
